 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(cells)
    components.sort(key=lambda cells: (min(c for r,c in cells), min(r for r,c in cells)))
    out = [row[:] for row in grid]
    n = len(components)
    # Alternate the highlighted components across the grid, with the phase set by parity.
    for i, cells in enumerate(components):
        if i % 2 == (0 if n % 2 else 1):
            for r, c in cells:
                out[r][c] = 8
    return out

if __name__ == '__main__':
    pass
